[IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String(($b64 -replace '\s', '')))
Write-Host "Created $zipPath" -ForegroundColor Green
if (Test-Path (Join-Path $here "SIGNOVA")) {
    Write-Host "A folder named SIGNOVA already exists - skipped extraction. Delete it or extract SIGNOVA.zip elsewhere." -ForegroundColor Yellow
} else {
    Expand-Archive -Path $zipPath -DestinationPath $here
    Write-Host "Extracted to $(Join-Path $here 'SIGNOVA')" -ForegroundColor Green
}
Write-Host ""
Write-Host "Next:" -ForegroundColor Magenta
Write-Host "  cd SIGNOVA"
Write-Host "  powershell -ExecutionPolicy Bypass -File .\setup_windows.ps1"
Write-Host "  powershell -ExecutionPolicy Bypass -File .\run_signova.ps1"
